15	/// The kind of forecasting algorithm that is available in the core domain.
16	///
17	/// New variants can be added without leaking implementation details to the
18	/// outside world.
19	#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Hash)]
20	pub enum ModelKind {
