116	/* ------------------------------------------------------------------------- */
117	/* ------------------------ Strategy Pattern (core) ------------------------ */
118	/* ------------------------------------------------------------------------- */
119	
120	/// The minimal set of methods that _any_ forecasting model must expose to the
121	/// core business logic.
122	///
123	/// The trait is object-safe so that different concrete implementations can be
124	/// handled via `Box<dyn ForecastModel>` in higher-level services.
125	pub trait ForecastModel: Send + Sync {
126	    /// Run inference for the given **feature matrix** (rows = samples).
127	    ///
128	    /// The exact data container type is opaque to the strategy; we use a
129	    /// simple `Vec<Vec<f64>>` to avoid pulling heavy ML crates into the core.
130	    fn predict(&self, features: &[Vec<f64>]) -> Result<Vec<f64>, ModelError>;
131	
132	    /// (Optional) Return a copy of the hyper-parameters that were used during
133	    /// training.  This is useful for audit and explainability.
134	    fn hyper_params(&self) -> HyperParams;
135	}
136	
137	/// Behaviour that a concrete _training_ strategy must fulfil.
138	///
139	/// Splitting this from `ForecastModel` allows us to decouple stateless
140	/// factories (they only know _how to_ create a model) from the stateful,
141	/// trained artefact (`ForecastModel`).
142	pub trait TrainableModelStrategy: Send + Sync {
143	    /// Human-readable name of the strategy (e.g. "Linear Regression").
144	    fn name(&self) -> &'static str;
145	
146	    /// Train the model with the given `dataset` and `hyper_params`.
147	    ///
148	    /// Returns a boxed `ForecastModel` that can later be stored in the
149	    /// registry or served by the inference endpoint.
150	    fn train(
151	        &self,
152	        dataset: &TrainingDataset,
153	        hyper_params: &HyperParams,
154	    ) -> Result<Box<dyn ForecastModel>, ModelError>;
155	
156	    /// Calculate evaluation metrics for the freshly trained model.
157	    fn evaluate(
158	        &self,
159	        model: &dyn ForecastModel,
160	        dataset: &TrainingDataset,
161	    ) -> Result<EvaluationSummary, ModelError>;
162	}
