164	/* ------------------------------------------------------------------------- */
165	/* ---------------- Concrete strategy: Linear Regression ------------------- */
166	/* ------------------------------------------------------------------------- */
167	
168	/// Dummy implementation of a linear regression forecasting model.
169	///
170	/// In the core layer we do **not** depend on any numerics crate; therefore,
171	/// the implementation is only a stub.  A real adapter (e.g. `linfa`) can
172	/// implement `TrainableModelStrategy` and `ForecastModel` behind the port.
173	#[derive(Debug, Clone)]
174	pub struct LinearRegressionModel {
175	    coefficients: Vec<f64>,
176	    intercept: f64,
177	    hyper_params: HyperParams,
178	}
179	
180	impl ForecastModel for LinearRegressionModel {
181	    fn predict(&self, features: &[Vec<f64>]) -> Result<Vec<f64>, ModelError> {
182	        let mut predictions = Vec::with_capacity(features.len());
183	        for row in features {
184	            if row.len() != self.coefficients.len() {
185	                return Err(ModelError::PredictionFailed(
186	                    "feature vector size does not match model coefficients".into(),
187	                ));
188	            }
189	            let y_hat = row
190	                .iter()
191	                .zip(self.coefficients.iter())
192	                .map(|(x, b)| x * b)
193	                .sum::<f64>()
194	                + self.intercept;
195	            predictions.push(y_hat);
196	        }
197	        Ok(predictions)
198	    }
199	
200	    fn hyper_params(&self) -> HyperParams {
201	        self.hyper_params.clone()
202	    }
203	}
