205	#[derive(Debug, Default)]
206	pub struct LinearRegressionStrategy;
207	
208	impl TrainableModelStrategy for LinearRegressionStrategy {
209	    fn name(&self) -> &'static str {
210	        "Linear Regression"
211	    }
212	
213	    fn train(
214	        &self,
215	        dataset: &TrainingDataset,
216	        hyper_params: &HyperParams,
217	    ) -> Result<Box<dyn ForecastModel>, ModelError> {
218	        // The following code is a **placeholder** that performs a naïve
219	        // ordinary least squares fit for 1-dimensional input. It should be
220	        // replaced by a robust algorithm in the infrastructure layer.
221	        let intercept = 0.0;
222	        let mut coefficients = Vec::new();
223	
224	        if dataset.features.is_empty() {
225	            return Err(ModelError::TrainingFailed(
226	                "cannot train on an empty dataset".into(),
227	            ));
228	        }
229	
230	        let feature_len = dataset.features[0].len();
231	        coefficients.resize(feature_len, 0.0);
232	
233	        Ok(Box::new(LinearRegressionModel {
234	            coefficients,
235	            intercept,
236	            hyper_params: hyper_params.clone(),
237	        }))
238	    }
239	
240	    fn evaluate(
241	        &self,
242	        model: &dyn ForecastModel,
243	        dataset: &TrainingDataset,
244	    ) -> Result<EvaluationSummary, ModelError> {
245	        let predictions = model.predict(&dataset.features)?;
246	        let mut sum_sq_err = 0.0;
247	        let mut sum_abs_err = 0.0;
248	
249	        for (y_true, y_pred) in dataset.targets.iter().zip(predictions.iter()) {
250	            let err = y_true - y_pred;
251	            sum_sq_err += err.powi(2);
252	            sum_abs_err += err.abs();
253	        }
254	
255	        let n = dataset.targets.len() as f64;
256	        let rmse = (sum_sq_err / n).sqrt();
257	        let mae = sum_abs_err / n;
258	
259	        Ok(EvaluationSummary::new(vec![
260	            MetricValue {
261	                kind: MetricKind::Rmse,
262	                value: rmse,
263	            },
264	            MetricValue {
265	                kind: MetricKind::Mae,
266	                value: mae,
267	            },
268	        ]))
269	    }
270	}
