2	//! Persistence adapters for ProfitPulse AI
3	//!
4	//! At the hexagonal‐architecture “adapter” layer we translate the
5	//! domain/port abstractions into concrete I/O against external systems
6	//! (SQLite for the Model Registry and `sled` for experiment tracking).
7	//!
8	//! The public surface of this module purposefully mirrors the ports that
9	//! live in `crate::ports`.  Downstream callers only depend on the ports;
10	//! they never talk to the concrete adapters directly, which keeps the
11	//! core isolated from infrastructure concerns.
12	
13	use std::path::PathBuf;
14	use std::sync::Arc;
15	
16	use async_trait::async_trait;
17	use chrono::{DateTime, Utc};
18	use serde::{Deserialize, Serialize};
19	use sled::IVec;
20	use sqlx::{migrate::MigrateDatabase, sqlite::SqlitePoolOptions, Pool, Sqlite};
21	use thiserror::Error;
22	use tokio::sync::Mutex;
23	
24	use crate::ports::{ExperimentStore, ModelRegistry};
25	
26	/// Convenience result type alias for all persistence‐related operations.
27	pub type Result<T> = std::result::Result<T, PersistenceError>;
28	
29	/// Errors that may occur while interacting with the persistence layer.
30	#[derive(Debug, Error)]
31	pub enum PersistenceError {
32	    #[error("SQLite error: {0}")]
33	    Sqlite(#[from] sqlx::Error),
34	
35	    #[error("sled error: {0}")]
36	    Sled(#[from] sled::Error),
37	
38	    #[error("JSON serialization/deserialization error: {0}")]
39	    SerdeJson(#[from] serde_json::Error),
40	
41	    #[error("Unknown model `{0}`")]
42	    ModelNotFound(String),
43	
44	    #[error("IO error: {0}")]
45	    Io(#[from] std::io::Error),
46	
47	    #[error("Experiment run not found: {0}")]
48	    ExperimentNotFound(String),
49	}
50	
51	/* -------------------------------------------------------------------------
52	 * Model Registry – SQLite implementation
53	 * ---------------------------------------------------------------------- */
54	
55	/// A single row in the `model_registry` table.
56	#[derive(Debug, Serialize, Deserialize, sqlx::FromRow, Clone)]
57	pub struct ModelMetadata {
58	    pub id: i64,
59	    pub model_name: String,
60	    pub version: String,
61	    pub created_at: DateTime<Utc>,
62	    pub hyperparams: serde_json::Value,
63	    pub metrics: serde_json::Value,
64	}
65	
66	/// Concrete implementation of the [`ModelRegistry`] port backed by SQLite.
67	#[derive(Debug, Clone)]
68	pub struct SqliteModelRegistry {
69	    pool: Arc<Pool<Sqlite>>,
70	}
71	
72	impl SqliteModelRegistry {
73	    /// Create a new registry.  If the database file does not exist yet we
74	    /// create it and run the embedded migrations.
75	    pub async fn new(db_path: impl Into<PathBuf>) -> Result<Self> {
76	        let path: PathBuf = db_path.into();
77	        let uri = format!("sqlite://{}", path.display());
78	
79	        // Create database file if it does not exist
80	        if !path.exists() {
81	            Sqlite::create_database(&uri).await.map_err(PersistenceError::Sqlite)?;
82	        }
83	
84	        let pool = SqlitePoolOptions::new()
85	            .max_connections(8)
86	            .connect(&uri)
87	            .await?;
88	
89	        // Run migrations (a single CREATE TABLE is enough for the demo)
90	        sqlx::query(
91	            r#"
92	            CREATE TABLE IF NOT EXISTS model_registry (
93	                id           INTEGER PRIMARY KEY AUTOINCREMENT,
94	                model_name   TEXT NOT NULL,
95	                version      TEXT NOT NULL,
96	                created_at   TEXT NOT NULL,
97	                hyperparams  TEXT NOT NULL,
98	                metrics      TEXT NOT NULL
99	            );
100	        "#,
101	        )
102	        .execute(&pool)
103	        .await?;
104	
105	        Ok(Self { pool: Arc::new(pool) })
106	    }
107	}
108	
109	#[async_trait]
110	impl ModelRegistry for SqliteModelRegistry {
111	    async fn register(
112	        &self,
113	        model_name: &str,
114	        version: &str,
115	        hyperparams: serde_json::Value,
116	        metrics: serde_json::Value,
117	    ) -> Result<()> {
118	        sqlx::query(
119	            r#"
120	            INSERT INTO model_registry (model_name, version, created_at, hyperparams, metrics)
121	            VALUES (?1, ?2, ?3, ?4, ?5)
122	        "#,
123	        )
124	        .bind(model_name)
125	        .bind(version)
126	        .bind(Utc::now())
127	        .bind(hyperparams)
128	        .bind(metrics)
129	        .execute(&*self.pool)
130	        .await?;
131	
132	        Ok(())
133	    }
134	
135	    async fn latest(&self, model_name: &str) -> Result<ModelMetadata> {
136	        sqlx::query_as::<_, ModelMetadata>(
137	            r#"
138	            SELECT *
139	            FROM   model_registry
140	            WHERE  model_name = ?1
141	            ORDER BY id DESC
142	            LIMIT 1
143	        "#,
144	        )
145	        .bind(model_name)
146	        .fetch_optional(&*self.pool)
147	        .await?
148	        .ok_or_else(|| PersistenceError::ModelNotFound(model_name.to_owned()))
149	    }
150	
151	    async fn list(&self, model_name: &str) -> Result<Vec<ModelMetadata>> {
152	        let models = sqlx::query_as::<_, ModelMetadata>(
153	            r#"
154	            SELECT *
155	            FROM   model_registry
156	            WHERE  model_name = ?1
157	            ORDER BY id DESC
158	        "#,
159	        )
160	        .bind(model_name)
161	        .fetch_all(&*self.pool)
162	        .await?;
163	
164	        Ok(models)
165	    }
166	}
