168	/* -------------------------------------------------------------------------
169	 * Experiment Store – sled implementation
170	 * ---------------------------------------------------------------------- */
171	
172	/// Immutable DTO representing a single experiment run.
173	#[derive(Debug, Serialize, Deserialize, Clone)]
174	pub struct ExperimentRun {
175	    pub run_id: String,
176	    pub experiment_name: String,
177	    pub started_at: DateTime<Utc>,
178	    pub finished_at: Option<DateTime<Utc>>,
179	    pub model_name: String,
180	    pub model_version: String,
181	    pub metrics: serde_json::Value,
182	    pub business_kpis: serde_json::Value,
183	}
184	
185	/// A thin wrapper around a `sled` database namespace.
186	///
187	/// Each experiment is stored as a JSON blob under the compound key
188	/// `{namespace}::{run_id}`.  Using namespaces keeps unrelated data
189	/// clearly separated within a single sled database file.
190	#[derive(Debug, Clone)]
191	pub struct SledExperimentStore {
192	    db: Arc<sled::Db>,
193	    namespace: Arc<str>,
194	    // A mutex guarantees atomic read‐modify‐write access to the namespace,
195	    // which sled does not provide out of the box.
196	    //
197	    // (In practice we’d use transactional sled APIs or rely on its single‐
198	    // writer property, but this is good enough for the demo.)
199	    lock: Arc<Mutex<()>>,
200	}
201	
202	impl SledExperimentStore {
203	    /// Open (or create) the sled store.
204	    ///
205	    /// The underlying DB is opened with default configuration; callers may
206	    /// choose to put it on an SSD or tmpfs for better performance.
207	    pub fn new(path: impl Into<PathBuf>, namespace: impl Into<Arc<str>>) -> Result<Self> {
208	        let db = sled::open(path.into())?;
209	        Ok(Self {
210	            db: Arc::new(db),
211	            namespace: namespace.into(),
212	            lock: Arc::new(Mutex::new(())),
213	        })
214	    }
215	
216	    /// Helper converting `{namespace}::{run_id}` into a unique sled key.
217	    fn make_key(&self, run_id: &str) -> String {
218	        format!("{}::{}", self.namespace, run_id)
219	    }
220	}
221	
222	#[async_trait]
223	impl ExperimentStore for SledExperimentStore {
224	    async fn log(&self, run: ExperimentRun) -> Result<()> {
225	        let key = self.make_key(&run.run_id);
226	        let value = serde_json::to_vec(&run)?;
227	
228	        let _guard = self.lock.lock().await; // Lock until write finishes
229	        self.db.insert(key.as_bytes(), value)?;
230	        self.db.flush_async().await?;
231	
232	        Ok(())
233	    }
234	
235	    async fn get(&self, run_id: &str) -> Result<ExperimentRun> {
236	        let key = self.make_key(run_id);
237	        let bytes: Option<IVec> = self.db.get(&key)?.map(|v| v.into());
238	
239	        match bytes {
240	            Some(ivec) => Ok(serde_json::from_slice(&ivec)?),
241	            None => Err(PersistenceError::ExperimentNotFound(run_id.to_owned())),
242	        }
243	    }
244	
245	    async fn list(&self) -> Result<Vec<ExperimentRun>> {
246	        let prefix = format!("{}::", self.namespace);
247	        let mut out = Vec::new();
248	
249	        for item in self.db.scan_prefix(&prefix) {
250	            let (_, val) = item?;
251	            let run: ExperimentRun = serde_json::from_slice(&val)?;
252	            out.push(run);
253	        }
254	
255	        // Sort descending by start date for convenience
256	        out.sort_by(|a, b| b.started_at.cmp(&a.started_at));
257	        Ok(out)
258	    }
259	}
