199	            let mut vec = bincode::serialize(&self.weights)
200	                .map_err(|e| CoreError::Other(format!("bincode: {e}")))?;
201	            vec.extend(bincode::serialize(&self.bias).map_err(|e| CoreError::Other(e.to_string()))?);
