206	            // Naïve deserialisation: first half is weights, second half is bias.
207	            // For demonstration we store the length at the beginning to split.
208	            //  ┌─────len(u32)──────┐┌────weights──────┐┌──bias(f32)──┐
209	            if bytes.len() < 4 {
210	                return Err(CoreError::InvalidInput(
211	                    "invalid linear-regression bytes".into(),
212	                ));
213	            }
214	            let len = u32::from_le_bytes(bytes[..4].try_into().unwrap()) as usize;
215	            let split = 4 + len;
216	            let weights: Vec<f32> = bincode::deserialize(&bytes[4..split])
217	                .map_err(|e| CoreError::Other(e.to_string()))?;
218	            let bias: f32 =
219	                bincode::deserialize(&bytes[split..]).map_err(|e| CoreError::Other(e.to_string()))?;
220	            Ok(Self { weights, bias })
