240	    /// Generic trainer interface so the core can host multiple strategies.
241	    pub trait Trainer {
242	        /// Trains a model on the provided dataset and returns both the fitted
243	        /// model and an evaluation [`TrainingReport`].
244	        fn train(&self, data: &Dataset) -> Result<(Box<dyn ForecastModel>, TrainingReport), CoreError>;
245	    }
246	
247	    /// Extremely small, *pedagogical* linear-regression trainer using
248	    /// the closed-form solution  θ = (XᵀX)⁻¹ Xᵀy.
249	    ///
250	    /// Never use this in production—gradient methods or libraries such as
251	    /// `linfa` would be preferable.  Again, the purpose is to show how the
252	    /// strategy can live in the core layer without outside dependencies.
253	    #[derive(Debug, Default)]
254	    pub struct LinearRegressionTrainer;
255	
256	    impl LinearRegressionTrainer {
257	        fn compute_weights(data: &Dataset) -> Result<(Vec<f32>, f32), CoreError> {
258	            if data.is_empty() {
259	                return Err(CoreError::InvalidInput("cannot train on empty dataset".into()));
260	            }
261	
262	            let feature_len = data.samples[0].features.len();
263	            // For closed-form we need XᵀX and Xᵀy.  We'll do it the naïve way.
264	            let mut xtx = vec![vec![0.0_f64; feature_len]; feature_len];
265	            let mut xty = vec![0.0_f64; feature_len];
266	            let mut bias = 0.0_f64;
267	
268	            for ForecastSample { features, target } in &data.samples {
269	                let target = *target as f64;
270	                for (i, &xi) in features.iter().enumerate() {
271	                    let xi = xi as f64;
272	                    xty[i] += xi * target;
273	                    for (j, &xj) in features.iter().enumerate().skip(i) {
274	                        let xj = xj as f64;
275	                        xtx[i][j] += xi * xj;
276	                        if i != j {
277	                            xtx[j][i] = xtx[i][j];
278	                        }
279	                    }
280	                    bias += target;
281	                }
282	            }
283	
284	            // Add a small ridge term λI to stabilise inversion.
285	            let lambda = 1e-6_f64;
286	            for i in 0..feature_len {
287	                xtx[i][i] += lambda;
288	            }
289	
290	            // Flatten xtx matrix for a dumb inversion (Gaussian elimination).
291	            // In real life we'd call `nalgebra`.
292	            let weights = crate::core::util::gaussian_solve(&xtx, &xty)?;
293	
294	            // Bias is simply the mean of residuals.
295	            bias /= data.len() as f64;
296	
297	            Ok((
298	                weights.iter().map(|&w| w as f32).collect(),
299	                bias as f32,
300	            ))
301	        }
302	
303	        fn compute_report(model: &LinearRegressionModel, data: &Dataset) -> TrainingReport {
304	            let (sum_sq, sum_abs, n) = data
305	                .samples
306	                .par_iter()
307	                .map(|s| {
308	                    let y_hat = model.predict(&s.features);
309	                    let err = (y_hat - s.target).abs();
310	                    (err * err, err, 1usize)
311	                })
312	                .reduce(
313	                    || (0.0, 0.0, 0),
314	                    |(ss1, sa1, n1), (ss2, sa2, n2)| (ss1 + ss2, sa1 + sa2, n1 + n2),
315	                );
316	
317	            TrainingReport {
318	                samples: n,
319	                rmse: (sum_sq / n as f32).sqrt(),
320	                mae: sum_abs / n as f32,
321	            }
322	        }
323	    }
324	
325	    impl Trainer for LinearRegressionTrainer {
326	        fn train(&self, data: &Dataset) -> Result<(Box<dyn ForecastModel>, TrainingReport), CoreError> {
327	            let (weights, bias) = Self::compute_weights(data)?;
328	            let model = LinearRegressionModel::new(weights, bias);
329	            let report = Self::compute_report(&model, data);
330	            Ok((Box::new(model), report))
331	        }
332	    }
333	}
