369	    impl<T: Trainer + Send + Sync + 'static> HyperparameterTuner for GridSearchTuner<T> {
370	        fn tune(
371	            &self,
372	            dataset: &Dataset,
373	        ) -> Result<(Box<dyn ForecastModel>, TrainingReport), CoreError> {
374	            use rayon::prelude::*;
375	
376	            let best = Arc::new(Mutex::new(None::<(Box<dyn ForecastModel>, TrainingReport, f32)>));
377	
378	            self.grid.par_iter().try_for_each(|&lambda| {
379	                let trainer = (self.trainer_factory)(lambda);
380	                let (model, report) = trainer.train(dataset)?;
381	                let mut guard = best.lock().unwrap();
382	                if guard
383	                    .as_ref()
384	                    .map(|(_, current, _)| report.rmse < current.rmse)
385	                    .unwrap_or(true)
386	                {
387	                    *guard = Some((model, report, lambda));
388	                }
389	                Ok::<_, CoreError>(())
390	            })?;
391	
392	            best.lock()
393	                .unwrap()
394	                .take()
395	                .map(|(m, r, _)| (m, r))
396	                .ok_or_else(|| CoreError::Other("grid search produced no result".into()))
397	        }
398	    }
