478	
479	    /// Solves a linear system using an extremely naïve Gaussian elimination.
480	    /// Returns the solution vector x.
481	    ///
482	    /// **Complexity:**  O(n³) – do not use for large matrices.
483	    pub fn gaussian_solve(a: &[Vec<f64>], b: &[f64]) -> Result<Vec<f64>, CoreError> {
484	        let n = a.len();
485	        let mut a = a.to_vec();
486	        let mut b = b.to_vec();
487	
488	        for i in 0..n {
489	            // Pivot
490	            let mut max_row = i;
491	            for k in i + 1..n {
492	                if a[k][i].abs() > a[max_row][i].abs() {
493	                    max_row = k;
494	                }
495	            }
496	            if a[max_row][i].abs() < 1e-12 {
497	                return Err(CoreError::Other("singular matrix".into()));
498	            }
499	            a.swap(i, max_row);
500	            b.swap(i, max_row);
501	
502	            // Normalize row
503	            let pivot = a[i][i];
504	            for j in i..n {
505	                a[i][j] /= pivot;
506	            }
507	            b[i] /= pivot;
508	
509	            // Eliminate
510	            for k in 0..n {
511	                if k != i {
512	                    let coeff = a[k][i];
513	                    for j in i..n {
514	                        a[k][j] -= coeff * a[i][j];
515	                    }
516	                    b[k] -= coeff * b[i];
517	                }
518	            }
519	        }
520	        Ok(b)
521	    }
522	}
