74	//! Data pre-processing pipeline definitions.
75	
76	use crate::error::ProfitPulseError;
77	use ndarray::{Array1, Array2, Axis};
78	use serde::{Deserialize, Serialize};
79	
80	/// A pluggable data pre-processing step.
81	pub trait DataPreprocessor: Send + Sync {
82	    /// Fit the internal state using the provided data.
83	    fn fit(&mut self, data: &Array2<f64>) -> Result<(), ProfitPulseError>;
84	
85	    /// Transform the provided data, returning a *new* allocation.
86	    fn transform(&self, data: &Array2<f64>) -> Result<Array2<f64>, ProfitPulseError>;
87	}
88	
89	/// Standard score normalisation (a.k.a. z-score).
90	///
91	/// Implements μ-σ scaling so that each column has zero mean and unit std-dev.
92	#[derive(Debug, Clone, Serialize, Deserialize)]
93	pub struct StandardScaler {
94	    mean: Option<Array1<f64>>,
95	    std: Option<Array1<f64>>,
96	}
97	
98	impl StandardScaler {
99	    /// Create a new, *un-fitted* scaler.
100	    pub fn new() -> Self {
101	        Self {
102	            mean: None,
103	            std: None,
104	        }
105	    }
106	
107	    fn assert_fitted(&self) -> Result<(), ProfitPulseError> {
108	        if self.mean.is_none() || self.std.is_none() {
109	            return Err(ProfitPulseError::Preprocessing(
110	                "Attempted to use an unfitted scaler".into(),
111	            ));
112	        }
113	        Ok(())
114	    }
115	}
116	
117	impl Default for StandardScaler {
118	    fn default() -> Self {
119	        Self::new()
120	    }
121	}
122	
123	impl DataPreprocessor for StandardScaler {
124	    fn fit(&mut self, data: &Array2<f64>) -> Result<(), ProfitPulseError> {
125	        let mean = data.mean_axis(Axis(0)).ok_or_else(|| {
126	            ProfitPulseError::Preprocessing("Failed to compute column means".to_string())
127	        })?;
128	        let var = data.var_axis(Axis(0), 0.0);
129	        let std = var.mapv(|v| v.sqrt().max(1e-12)); // Avoid divide-by-zero
130	
131	        self.mean = Some(mean);
132	        self.std = Some(std);
133	        Ok(())
134	    }
135	
136	    fn transform(&self, data: &Array2<f64>) -> Result<Array2<f64>, ProfitPulseError> {
137	        self.assert_fitted()?;
138	
139	        let mean = self.mean.as_ref().unwrap();
140	        let std = self.std.as_ref().unwrap();
141	
142	        let mut result = data.clone();
143	        for ((mut col), (&m, &s)) in
144	            result.columns_mut().into_iter().zip(mean.iter().zip(std.iter()))
145	        {
146	            col -= m;
147	            col /= s;
148	        }
149	        Ok(result)
150	    }
151	}
