179	/// A very small linear regression inference implementation.
180	///
181	/// Training lives elsewhere; here we only need the learned parameters.
182	#[derive(Debug, Clone, Serialize, Deserialize)]
183	pub struct LinearRegressionModel {
184	    coefficients: Array1<f64>,
185	    intercept: f64,
186	    version: String,
187	}
188	
189	impl LinearRegressionModel {
190	    /// Create a new instance directly from coefficients.
191	    pub fn new(coefficients: Array1<f64>, intercept: f64, version: impl Into<String>) -> Self {
192	        Self {
193	            coefficients,
194	            intercept,
195	            version: version.into(),
196	        }
197	    }
198	}
199	
200	impl Model for LinearRegressionModel {
201	    type Input = Array2<f64>;
202	    type Output = Array1<f64>;
203	
204	    fn predict(&self, input: &Self::Input) -> Result<Self::Output, ProfitPulseError> {
205	        if input.ncols() != self.coefficients.len() {
206	            return Err(ProfitPulseError::Inference(format!(
207	                "Feature dimension mismatch: model expects {}, received {}",
208	                self.coefficients.len(),
209	                input.ncols()
210	            )));
211	        }
212	
213	        let mut preds = input.dot(&self.coefficients);
214	        preds += self.intercept;
215	        Ok(preds)
216	    }
217	
218	    fn version(&self) -> &str {
219	        &self.version
220	    }
221	
222	    fn name(&self) -> &'static str {
223	        "linear_regression"
224	    }
225	}
