331	//! High level orchestration façade.
332	
333	use crate::{
334	    error::ProfitPulseError,
335	    factory::{DynModel, ModelFactory},
336	    preprocessing::DataPreprocessor,
337	    registry::ModelRegistry,
338	};
339	use ndarray::{Array1, Array2};
340	
341	/// Convenience type alias.
342	pub type Prediction = Array1<f64>;
343	
344	/// Responsible for fetching models, running preprocessors, and producing
345	/// predictions.  Meant to be *stateless* – create one per request if needed.
346	pub struct InferenceEngine<R: ModelRegistry> {
347	    registry: R,
348	}
349	
350	impl<R: ModelRegistry> InferenceEngine<R> {
351	    /// Build a new engine with the given registry implementation.
352	    pub fn new(registry: R) -> Self {
353	        Self { registry }
354	    }
355	
356	    /// Runs the full prediction flow.
357	    ///
358	    /// * `model_name` – business key
359	    /// * `input` – raw features (rows = samples, cols = features)
360	    /// * `preprocessors` – ordered pipeline
361	    pub fn predict(
362	        &self,
363	        model_name: &str,
364	        input: &Array2<f64>,
365	        mut preprocessors: Vec<Box<dyn DataPreprocessor>>,
366	    ) -> Result<Prediction, ProfitPulseError> {
367	        // 1. fetch model artifact
368	        let artifact = self.registry.fetch_latest(model_name)?;
369	        // 2. build concrete model
370	        let model: DynModel = ModelFactory::build(&artifact)?;
371	
372	        // 3. Fit each preprocessor on full training set? For inference we only transform.
373	        //    We assume preprocessors are already fitted offline and deserialised with model.
374	        //    Here, we just run transform.
375	        let mut data = input.clone();
376	        for pre in preprocessors.iter() {
377	            data = pre.transform(&data)?;
378	        }
379	
380	        // 4. run inference
381	        model.predict(&data)
382	    }
383	}
