80	mod adapters {
81	    //! Concrete implementations for the previously defined ports.
82	    //!
83	    //! 1. `SqliteModelRegistry` – stores metadata + binary artefacts
84	    //!    inside an embedded SQLite DB.
85	    //! 2. `LinfaInferenceEngine`  – deserialises a Linfa model and
86	    //!    produces predictions.
87	
88	    use super::domain::{ForecastInput, ForecastOutput, ModelVersion};
89	    use super::ports::{InferenceEngine, ModelRegistry};
90	    use anyhow::{anyhow, Context, Result};
91	    use chrono::{DateTime, Utc};
92	    use rusqlite::{named_params, Connection, OptionalExtension};
93	    use serde_json::Value;
94	    use std::path::Path;
95	
96	    /* ------------------------------------------------------------------ *
97	     * SQLite MODEL REGISTRY                                              *
98	     * ------------------------------------------------------------------ */
99	
100	    pub struct SqliteModelRegistry {
101	        conn: Connection,
102	    }
103	
104	    impl SqliteModelRegistry {
105	        pub fn new<P: AsRef<Path>>(db_path: P) -> Result<Self> {
106	            let conn = Connection::open(db_path.as_ref())
107	                .with_context(|| "opening/creating SQLite registry")?;
108	            Self::init_schema(&conn)?;
109	            Ok(Self { conn })
110	        }
111	
112	        fn init_schema(conn: &Connection) -> Result<()> {
113	            conn.execute_batch(
114	                r#"
115	                PRAGMA foreign_keys = ON;
116	
117	                CREATE TABLE IF NOT EXISTS models (
118	                    id           INTEGER PRIMARY KEY AUTOINCREMENT,
119	                    name         TEXT NOT NULL,
120	                    algorithm    TEXT NOT NULL,
121	                    version      INTEGER NOT NULL,
122	                    hyperparams  TEXT NOT NULL,
123	                    created_at   TEXT NOT NULL
124	                );
125	
126	                CREATE UNIQUE INDEX IF NOT EXISTS idx_model_name_version
127	                    ON models(name, version);
128	
129	                CREATE TABLE IF NOT EXISTS model_artifacts (
130	                    model_id INTEGER PRIMARY KEY,
131	                    artifact BLOB NOT NULL,
132	                    FOREIGN KEY(model_id) REFERENCES models(id) ON DELETE CASCADE
133	                );
134	                "#,
135	            )?;
136	            Ok(())
137	        }
138	
139	        fn latest_version(&self, name: &str) -> Result<Option<i32>> {
140	            let sql = "SELECT MAX(version) FROM models WHERE name = ?1";
141	            let version: Option<i32> =
142	                self.conn.query_row(sql, [name], |row| row.get(0)).optional()?;
143	            Ok(version.flatten())
144	        }
145	    }
146	
147	    impl ModelRegistry for SqliteModelRegistry {
148	        fn fetch_latest(&self, model_name: &str) -> Result<ModelVersion> {
149	            let sql = r#"
150	                SELECT id, name, algorithm, version, hyperparams, created_at
151	                  FROM models
152	                 WHERE name = ?1
153	              ORDER BY version DESC
154	                 LIMIT 1
155	            "#;
156	            self.conn
157	                .query_row(sql, [model_name], |row| {
158	                    let hyperparams: String = row.get(4)?;
159	                    Ok(ModelVersion {
160	                        id: row.get(0)?,
161	                        name: row.get(1)?,
162	                        algorithm: row.get(2)?,
163	                        version: row.get(3)?,
164	                        hyperparams: serde_json::from_str(&hyperparams).unwrap_or_default(),
165	                        created_at: DateTime::parse_from_rfc3339(&row.get::<_, String>(5)?)
166	                            .unwrap()
167	                            .with_timezone(&Utc),
168	                    })
169	                })
170	                .optional()?
171	                .ok_or_else(|| anyhow!("model `{model_name}` not found"))
172	        }
173	
174	        fn save(&self, metadata: &ModelVersion, model_bytes: &[u8]) -> Result<()> {
175	            let tx = self.conn.transaction()?;
176	            tx.execute(
177	                r#"
178	                INSERT INTO models (name, algorithm, version, hyperparams, created_at)
179	                     VALUES (:name, :algorithm, :version, :hyperparams, :created_at)
180	                "#,
181	                named_params! {
182	                    ":name":        &metadata.name,
183	                    ":algorithm":   &metadata.algorithm,
184	                    ":version":     metadata.version,
185	                    ":hyperparams": metadata.hyperparams.to_string(),
186	                    ":created_at":  metadata.created_at.to_rfc3339(),
187	                },
188	            )?;
189	
190	            let model_id = tx.last_insert_rowid();
191	            tx.execute(
192	                "INSERT INTO model_artifacts (model_id, artifact) VALUES (?1, ?2)",
193	                (model_id, model_bytes),
194	            )?;
195	            tx.commit()?;
196	            Ok(())
197	        }
198	
199	        fn load_bytes(&self, metadata: &ModelVersion) -> Result<Vec<u8>> {
200	            let sql = "SELECT artifact FROM model_artifacts WHERE model_id = ?1";
201	            let bytes = self
202	                .conn
203	                .query_row(sql, [metadata.id], |row| row.get(0))
204	                .optional()?
205	                .ok_or_else(|| anyhow!("binary artifact for model {} not found", metadata.id))?;
206	            Ok(bytes)
207	        }
208	    }
