281	    pub fn train_and_register_linear_model<P: AsRef<Path>>(
282	        csv_path: P,
283	        target_column: &str,
284	        model_name: &str,
285	        registry_path: P,
286	    ) -> Result<()> {
287	        let (x, y) = load_csv_dataset(csv_path, target_column)?;
288	
289	        let ds = linfa::Dataset::new(x, y);
290	        let model = linfa_linear::LinearRegression::default()
291	            .fit(&ds)
292	            .context("fitting linear regression")?;
293	
294	        // Compute simple RMSE on the training set as a demo metric
295	        let predictions = model.predict(&ds);
296	        let rmse = predictions
297	            .mean_squared_error(&ds)?
298	            .sqrt(); // root
299	
300	        info!("Training finished – RMSE on training set: {:.4}", rmse);
301	
302	        let bytes = bincode::serialize(&model).context("serialising model")?;
303	
304	        // Register model
305	        let registry = SqliteModelRegistry::new(registry_path)?;
306	        let metadata = registry.create_next_metadata(
307	            model_name,
308	            "linear_regression",
309	            &serde_json::json!({
310	                "alpha": 1.0, // dummy param for illustration purposes
311	                "rmse_train": rmse,
312	            }),
313	        )?;
314	        registry.save(&metadata, &bytes)?;
315	        info!(
316	            "Model `{}` v{} stored in registry",
317	            metadata.name, metadata.version
318	        );
319	        Ok(())
320	    }
