350	    fn load_csv_dataset<P: AsRef<Path>>(
351	        csv_path: P,
352	        target_column: &str,
353	    ) -> Result<(Array2<f64>, Array1<f64>)> {
354	        use csv::ReaderBuilder;
355	
356	        let mut rdr = ReaderBuilder::new()
357	            .has_headers(true)
358	            .from_path(csv_path.as_ref())
359	            .with_context(|| "opening CSV file")?;
360	
361	        let headers = rdr
362	            .headers()
363	            .context("reading CSV headers")?
364	            .clone();
365	
366	        // Determine the target index
367	        let target_idx = headers
368	            .iter()
369	            .position(|h| h == target_column)
370	            .ok_or_else(|| anyhow!("target column `{}` not found", target_column))?;
371	
372	        let feature_indices: Vec<usize> = (0..headers.len())
373	            .filter(|&idx| idx != target_idx)
374	            .collect();
375	
376	        let mut target: Vec<f64> = Vec::new();
377	        let mut features: Vec<f64> = Vec::new();
378	        let mut row_count = 0usize;
379	
380	        for result in rdr.records() {
381	            let rec = result?;
382	            target.push(
383	                rec.get(target_idx)
384	                    .ok_or_else(|| anyhow!("missing target field"))?
385	                    .parse::<f64>()?,
386	            );
387	
388	            for &fi in &feature_indices {
389	                features.push(
390	                    rec.get(fi)
391	                        .ok_or_else(|| anyhow!("missing feature field"))?
392	                        .parse::<f64>()?,
393	                );
394	            }
395	            row_count += 1;
396	        }
397	
398	        let n_features = feature_indices.len();
399	        let features = Array2::from_shape_vec((row_count, n_features), features)
400	            .context("building ndarray feature matrix")?;
401	        let target = Array1::from(target);
402	
403	        Ok((features, target))
404	    }
405	}
