174	        fn save(&self, metadata: &ModelVersion, model_bytes: &[u8]) -> Result<()> {
175	            let tx = self.conn.transaction()?;
176	            tx.execute(
177	                r#"
178	                INSERT INTO models (name, algorithm, version, hyperparams, created_at)
179	                     VALUES (:name, :algorithm, :version, :hyperparams, :created_at)
180	                "#,
