118	/// Smoke-tests that concurrent invocations of `forecast` work correctly and
119	/// do not suffer from database lock contention inside the SQLite-backed
120	/// model registry.  We spawn N child processes in parallel and wait for
121	/// them to succeed.
122	#[test]
123	fn concurrent_forecasts_do_not_deadlock() -> anyhow::Result<()> {
124	    const PARALLELISM: usize = 4;
125	    let barrier = Arc::new(Barrier::new(PARALLELISM));
126	    let mut handles = Vec::with_capacity(PARALLELISM);
127	
128	    for _ in 0..PARALLELISM {
129	        let barrier = barrier.clone();
130	        handles.push(thread::spawn(move || {
131	            // Synchronise thread start-up so that processes overlap and are
132	            // more likely to trigger locking issues.
133	            barrier.wait();
134	
135	            // Re-use the helper; any I/O errors propagate via thread::Result.
136	            let csv_file = write_sample_sales_csv().expect("temp-file creation failed");
137	            let csv_path: PathBuf = csv_file.path().into();
138	
139	            cli()
140	                .arg("forecast")
141	                .arg("--model")
142	                .arg("linear-regression")
143	                .arg("--input")
144	                .arg(csv_path)
145	                .assert()
146	                .success()
147	                .stdout(predicate::str::contains(r#""prediction"#));
148	        }));
149	    }
150	
151	    // Join threads with a generous timeout so that CI doesn’t hang forever
152	    // on a genuine dead-lock; tweak if the models become computationally
153	    // heavier in the future.
154	    for handle in handles {
155	        let join = handle.join();
156	        assert!(
157	            join.is_ok(),
158	            "concurrent forecast thread panicked: {join:?}"
159	        );
160	    }
161	
162	    Ok(())
163	}
