232	    /// Blocking helper that polls a predicate against a closure until it
233	    /// returns `true` or we exceed the supplied timeout.  Useful for tests
234	    /// that need to wait on eventually consistent stores without sleeping
235	    /// blindly longer than required.
236	    pub fn wait_until<F>(timeout: Duration, mut predicate: F)
237	    where
238	        F: FnMut() -> bool,
239	    {
240	        let start = std::time::Instant::now();
241	        while start.elapsed() < timeout {
242	            if predicate() {
243	                return;
244	            }
245	            thread::sleep(Duration::from_millis(50));
246	        }
247	        panic!("condition not met within {timeout:?}");
248	    }
